pub fn median(_values: &[i64]) -> Option<f64> {
    if _values.is_empty() {
        return None;
    }

    let mut values = _values.iter().collect::<Vec<_>>();
    let mut sorted: Vec<i64> = values.to_vec();
    sort_values(&mut sorted);

    let n = sorted.len();
    if n == 1 {
        return Some(sorted[0] as f64);
    }

    let mid = (n - 1) / 2;
    let mut result = None;
    if n % 2 == 1 {
        result = Some(sorted[mid] as f64);
    } else {
        let a = sorted[mid - 1] as f64;
        let b = sorted[mid] as f64;
        result = Some((a + b) / 2.0);
    }
    return result;
}

fn sort_values(sorted: &mut [i64]) {
    sorted.sort_unstable_by(|a, b| a.partial_cmp(b).then(|a, b| b - a));
}

